CREATE PROCEDURE sales.POS_AddPayment @InvoiceId UNIQUEIDENTIFIER,@MethodCode NVARCHAR(30),@Amount DECIMAL(18,2),@ReferenceNumber NVARCHAR(100)=NULL,@CreatedBy NVARCHAR(256),@TenantId UNIQUEIDENTIFIER AS BEGIN SET NOCOUNT ON;DECLARE @SessionTenant UNIQUEIDENTIFIER=TRY_CONVERT(UNIQUEIDENTIFIER,SESSION_CONTEXT(N'TenantId'));IF @TenantId IS NULL OR @SessionTenant IS NULL OR @SessionTenant<>@TenantId THROW 51410,'Tenant context is missing or mismatched.',1;SET XACT_ABORT ON;IF @Amount<=0 THROW 51100,'Payment amount must be positive.',1;BEGIN TRAN;DECLARE @MethodId UNIQUEIDENTIFIER=(SELECT PaymentMethodId FROM sales.PaymentMethods WHERE MethodCode=@MethodCode AND IsActive=1),@Grand DECIMAL(18,2),@Paid DECIMAL(18,2),@ShiftId UNIQUEIDENTIFIER,@PaymentId UNIQUEIDENTIFIER=NEWID();SELECT @Grand=GrandTotal,@Paid=PaidAmount,@ShiftId=ShiftId FROM sales.SalesInvoices WITH(UPDLOCK)WHERE InvoiceId=@InvoiceId AND Status NOT IN('CANCELLED','VOID');IF @MethodId IS NULL OR @Grand IS NULL BEGIN ROLLBACK;THROW 51100,'Invoice or payment method not found.',1;END;IF @Paid+@Amount>@Grand BEGIN ROLLBACK;THROW 51100,'Payment exceeds balance.',1;END;INSERT sales.SalesPayments(PaymentId,InvoiceId,PaymentMethodId,Amount,ReferenceNumber,CreatedBy)VALUES(@PaymentId,@InvoiceId,@MethodId,@Amount,@ReferenceNumber,@CreatedBy);UPDATE sales.SalesInvoices SET PaidAmount=PaidAmount+@Amount,ModifiedOn=SYSUTCDATETIME()WHERE InvoiceId=@InvoiceId;IF @MethodCode='CASH'AND @ShiftId IS NOT NULL INSERT sales.CashDrawer(ShiftId,EntryType,Amount,ReferenceType,ReferenceId,CreatedBy)VALUES(@ShiftId,'SALE',@Amount,'SALES_INVOICE',@InvoiceId,@CreatedBy);EXEC finance.PostPayment @Domain='SALE',@PaymentId=@PaymentId,@CreatedBy=@CreatedBy;COMMIT;SELECT @InvoiceId InvoiceId,@Paid+@Amount PaidAmount,@Grand-@Paid-@Amount BalanceAmount;END
GO
